-- ============================================================
-- Kantina ERP database (inventory + sales ledger)
-- Owns: item master (SKU, price, stock), stock movements,
--       sales orders (online from Kantina + walk-in), reports.
-- Tables use the erp_ prefix so this can share one database
-- with the other apps if the host only allows one.
-- Import into the database named in erp/config (default: kantina_erp).
-- ============================================================
SET NAMES utf8mb4;
SET time_zone = '+08:00';
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS erp_webhook_deliveries;
DROP TABLE IF EXISTS erp_sales_order_lines;
DROP TABLE IF EXISTS erp_sales_orders;
DROP TABLE IF EXISTS erp_stock_movements;
DROP TABLE IF EXISTS erp_products;
DROP TABLE IF EXISTS erp_stalls;
DROP TABLE IF EXISTS erp_admins;

SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE erp_admins (
  id            INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  username      VARCHAR(40)  NOT NULL UNIQUE,
  name          VARCHAR(120) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Each stall is a cost center in the ERP
CREATE TABLE erp_stalls (
  code        VARCHAR(40) NOT NULL PRIMARY KEY,   -- same id as Kantina / CMS (e.g. lolas-silog)
  name        VARCHAR(80) NOT NULL,
  cost_center VARCHAR(20) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE erp_products (
  sku           VARCHAR(40)   NOT NULL PRIMARY KEY,
  stall_code    VARCHAR(40)   NOT NULL,
  name          VARCHAR(80)   NOT NULL,
  type          ENUM('menu','addon') NOT NULL DEFAULT 'menu',
  price         DECIMAL(10,2) NOT NULL,
  stock         INT           NOT NULL DEFAULT 0,
  track_stock   TINYINT(1)    NOT NULL DEFAULT 1,     -- 0 = made to order, never runs out
  reorder_level INT           NOT NULL DEFAULT 5,
  is_active     TINYINT(1)    NOT NULL DEFAULT 1,     -- 0 = not for sale
  created_at    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_erp_product_stall FOREIGN KEY (stall_code) REFERENCES erp_stalls(code) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE erp_stock_movements (
  id            BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  sku           VARCHAR(40)  NOT NULL,
  qty_change    INT          NOT NULL,
  balance_after INT          NOT NULL,
  reason        ENUM('opening','sale','sale_cancel','restock','adjustment') NOT NULL,
  reference     VARCHAR(40)  NULL,                    -- SO number, restock note, etc.
  note          VARCHAR(255) NULL,
  created_by    VARCHAR(60)  NOT NULL DEFAULT 'system',
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_erp_mov_sku (sku, created_at),
  CONSTRAINT fk_erp_mov_product FOREIGN KEY (sku) REFERENCES erp_products(sku) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE erp_sales_orders (
  id           INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  so_no        VARCHAR(20)   NULL UNIQUE,             -- SO-000123 (set right after insert)
  channel      ENUM('kantina','walk_in') NOT NULL DEFAULT 'kantina',
  external_ref VARCHAR(40)   NULL UNIQUE,             -- Kantina order ref, e.g. KTN-90214 (makes retries idempotent)
  stall_code   VARCHAR(40)   NOT NULL,
  status       ENUM('open','paid','cancelled') NOT NULL DEFAULT 'open',
  total        DECIMAL(10,2) NOT NULL DEFAULT 0,
  created_at   DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP,
  paid_at      DATETIME      NULL,
  cancelled_at DATETIME      NULL,
  KEY idx_erp_so_report (stall_code, status, created_at),
  CONSTRAINT fk_erp_so_stall FOREIGN KEY (stall_code) REFERENCES erp_stalls(code) ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE erp_sales_order_lines (
  id             BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  sales_order_id INT UNSIGNED  NOT NULL,
  sku            VARCHAR(40)   NOT NULL,
  name           VARCHAR(80)   NOT NULL,
  qty            INT           NOT NULL,
  unit_price     DECIMAL(10,2) NOT NULL,
  line_total     DECIMAL(10,2) NOT NULL,
  KEY idx_erp_line_sku (sku),
  CONSTRAINT fk_erp_line_so FOREIGN KEY (sales_order_id) REFERENCES erp_sales_orders(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Outgoing webhooks (product.updated, stock.low, stock.depleted) sent to Kantina
CREATE TABLE erp_webhook_deliveries (
  id            BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  event_id      VARCHAR(40)  NOT NULL UNIQUE,
  event         VARCHAR(60)  NOT NULL,
  payload       TEXT         NOT NULL,
  status        ENUM('pending','delivered','failed') NOT NULL DEFAULT 'pending',
  attempts      INT          NOT NULL DEFAULT 0,
  response_code SMALLINT     NULL,
  last_error    TEXT         NULL,
  created_at    DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  delivered_at  DATETIME     NULL,
  KEY idx_erp_wh_status (status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

